messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: two cars race on a straight track toward a visible finish line. One car is bright RED, the other bright BLUE. The blue car leads early, then the red car accelerates, overtakes mid-race, and wins. After the red car crosses the finish line the race resets and loops forever. Both cars must be clearly visible and large enough to follow throughout (fill a meaningful part of the frame). Simple ground and sky, camera keeps both cars in view. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Car Race</title>
<style>
*{margin:0;padding:0;box-sizing:border-box}
body{overflow:hidden;background:#000}
canvas{display:block}
</style>
</head>
<body>
<script type="module">
import * as THREE from './three.module.js';

// ─── Renderer ───
const renderer = new THREE.WebGLRenderer({antialias:true});
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.0;
document.body.appendChild(renderer.domElement);

// ─── Scene ───
const scene = new THREE.Scene();
scene.fog = new THREE.FogExp2(0x87CEEB, 0.0018);

// ─── Camera ───
const camera = new THREE.PerspectiveCamera(55, window.innerWidth/window.innerHeight, 0.1, 1000);

// ─── Lights ───
const hemiLight = new THREE.HemisphereLight(0x87CEEB, 0x444422, 0.6);
scene.add(hemiLight);

const dirLight = new THREE.DirectionalLight(0xfff0dd, 1.8);
dirLight.position.set(30, 50, 20);
dirLight.castShadow = true;
dirLight.shadow.mapSize.set(2048, 2048);
dirLight.shadow.camera.left = -30;
dirLight.shadow.camera.right = 30;
dirLight.shadow.camera.top = 30;
dirLight.shadow.camera.bottom = -30;
dirLight.shadow.camera.near = 1;
dirLight.shadow.camera.far = 120;
dirLight.shadow.bias = -0.001;
scene.add(dirLight);

const fillLight = new THREE.DirectionalLight(0x8899cc, 0.3);
fillLight.position.set(-20, 15, -10);
scene.add(fillLight);

// ─── Sky ───
const skyGeo = new THREE.SphereGeometry(400, 32, 32);
const skyMat = new THREE.ShaderMaterial({
  side: THREE.BackSide,
  uniforms: {
    topColor: {value: new THREE.Color(0x0044aa)},
    bottomColor: {value: new THREE.Color(0xffeedd)},
    offset: {value: 20},
    exponent: {value: 0.4}
  },
  vertexShader: `
    varying vec3 vWorldPosition;
    void main(){
      vec4 wp = modelMatrix * vec4(position,1.0);
      vWorldPosition = wp.xyz;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0);
    }
  `,
  fragmentShader: `
    uniform vec3 topColor;
    uniform vec3 bottomColor;
    uniform float offset;
    uniform float exponent;
    varying vec3 vWorldPosition;
    void main(){
      float h = normalize(vWorldPosition + offset).y;
      gl_FragColor = vec4(mix(bottomColor, topColor, max(pow(max(h,0.0), exponent),0.0)), 1.0);
    }
  `
});
scene.add(new THREE.Mesh(skyGeo, skyMat));

// ─── Ground ───
const groundGeo = new THREE.PlaneGeometry(120, 500);
const groundMat = new THREE.MeshLambertMaterial({color: 0x3a7d3a});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI/2;
ground.position.set(0, -0.25, -180);
ground.receiveShadow = true;
scene.add(ground);

// ─── Track ───
const trackGeo = new THREE.PlaneGeometry(12, 450);
const trackMat = new THREE.MeshLambertMaterial({color: 0x444444});
const track = new THREE.Mesh(trackGeo, trackMat);
track.rotation.x = -Math.PI/2;
track.position.set(0, -0.15, -165);
track.receiveShadow = true;
scene.add(track);

// Track edge lines
const edgeGeo = new THREE.PlaneGeometry(0.15, 450);
const edgeMat = new THREE.MeshLambertMaterial({color: 0xffffff});
const edgeL = new THREE.Mesh(edgeGeo, edgeMat);
edgeL.rotation.x = -Math.PI/2;
edgeL.position.set(-5.85, -0.1, -165);
scene.add(edgeL);
const edgeR = edgeL.clone();
edgeR.position.x = 5.85;
scene.add(edgeR);

// Lane divider (dashed)
for(let z = -385; z < 55; z += 4){
  const dashGeo = new THREE.PlaneGeometry(0.1, 2);
  const dash = new THREE.Mesh(dashGeo, edgeMat);
  dash.rotation.x = -Math.PI/2;
  dash.position.set(0, -0.1, z);
  scene.add(dash);
}

// ─── Finish Line ───
const FL_Z = 35;
const FL_CHECKER_SIZE = 1.2;
const FL_CHECKER_COLS = 10;
const FL_CHECKER_ROWS = 2;
const FL_CHECKER_TOTAL_W = FL_CHECKER_COLS * FL_CHECKER_SIZE;
const FL_CHECKER_TOTAL_H = FL_CHECKER_ROWS * FL_CHECKER_SIZE;

for(let c = 0; c < FL_CHECKER_COLS; c++){
  for(let r = 0; r < FL_CHECKER_ROWS; r++){
    const color = (c + r) % 2 === 0 ? 0xffffff : 0x111111;
    const cg = new THREE.PlaneGeometry(FL_CHECKER_SIZE, FL_CHECKER_SIZE);
    const cm = new THREE.MeshLambertMaterial({color});
    const checker = new THREE.Mesh(cg, cm);
    checker.rotation.x = -Math.PI/2;
    checker.position.set(
      -FL_CHECKER_TOTAL_W/2 + c * FL_CHECKER_SIZE + FL_CHECKER_SIZE/2,
      -0.08,
      FL_Z - FL_CHECKER_TOTAL_H/2 + r * FL_CHECKER_SIZE + FL_CHECKER_SIZE/2
    );
    scene.add(checker);
  }
}

// Finish arch
const archMat = new THREE.MeshLambertMaterial({color: 0xffffff});
const archPoleGeo = new THREE.CylinderGeometry(0.15, 0.15, 8, 8);
const archPoleL = new THREE.Mesh(archPoleGeo, archMat);
archPoleL.position.set(-6, 4, FL_Z);
archPoleL.castShadow = true;
scene.add(archPoleL);
const archPoleR = archPoleL.clone();
archPoleR.position.x = 6;
scene.add(archPoleR);

const archBarGeo = new THREE.BoxGeometry(12.3, 1.0, 0.3);
const archBar = new THREE.Mesh(archBarGeo, archMat);
archBar.position.set(0, 8.2, FL_Z);
archBar.castShadow = true;
scene.add(archBar);

// "FINISH" banner on arch
const bannerGeo = new THREE.PlaneGeometry(8, 1.2);
const canvas = document.createElement('canvas');
canvas.width = 512;
canvas.height = 76;
const ctx = canvas.getContext('2d');
ctx.fillStyle = '#cc0000';
ctx.fillRect(0, 0, 512, 76);
ctx.fillStyle = '#ffffff';
ctx.font = 'bold 52px Arial';
ctx.textAlign = 'center';
ctx.textBaseline = 'middle';
ctx.fillText('F I N I S H', 256, 38);
const bannerTex = new THREE.CanvasTexture(canvas);
const bannerMat = new THREE.MeshLambertMaterial({map: bannerTex});
const banner = new THREE.Mesh(bannerGeo, bannerMat);
banner.position.set(0, 8.2, FL_Z + 0.2);
scene.add(banner);

// ─── Start Line ───
const SL_Z = -375;
const slGeo = new THREE.PlaneGeometry(12, 0.3);
const slMat = new THREE.MeshLambertMaterial({color: 0xffffff});
const startLine = new THREE.Mesh(slGeo, slMat);
startLine.rotation.x = -Math.PI/2;
startLine.position.set(0, -0.09, SL_Z);
scene.add(startLine);

// ─── Scenery ───
function createTree(x, z){
  const g = new THREE.Group();
  const trunkGeo = new THREE.CylinderGeometry(0.2, 0.3, 3, 6);
  const trunkMat = new THREE.MeshLambertMaterial({color: 0x8B4513});
  const trunk = new THREE.Mesh(trunkGeo, trunkMat);
  trunk.position.y = 1.5;
  trunk.castShadow = true;
  g.add(trunk);
  const foliageGeo = new THREE.SphereGeometry(1.5, 8, 6);
  const foliageMat = new THREE.MeshLambertMaterial({color: 0x228B22});
  const foliage = new THREE.Mesh(foliageGeo, foliageMat);
  foliage.position.y = 4;
  foliage.castShadow = true;
  g.add(foliage);
  g.position.set(x, 0, z);
  scene.add(g);
}

for(let z = -380; z < FL_Z + 10; z += 15){
  createTree(-12 - Math.random()*5, z);
  createTree(12 + Math.random()*5, z);
}

// ─── Car Factory ───
function createCar(color){
  const car = new THREE.Group();
  const bodyMat = new THREE.MeshPhongMaterial({color, shininess: 120, specular: 0x444444});
  const cabinMat = new THREE.MeshPhongMaterial({color: 0x88ccff, shininess: 200, specular: 0xffffff, transparent: true, opacity: 0.6});
  const wheelMat = new THREE.MeshPhongMaterial({color: 0x111111, shininess: 10});
  const chromeMat = new THREE.MeshPhongMaterial({color: 0xcccccc, shininess: 250, specular: 0xffffff});

  // Body
  const bodyGeo = new THREE.BoxGeometry(3.2, 0.6, 1.6);
  const body = new THREE.Mesh(bodyGeo, bodyMat);
  body.position.y = 0.4;
  body.castShadow = true;
  car.add(body);

  // Cabin
  const cabinGeo = new THREE.BoxGeometry(1.6, 0.55, 1.3);
  const cabin = new THREE.Mesh(cabinGeo, cabinMat);
  cabin.position.set(-0.15, 0.92, 0);
  cabin.castShadow = true;
  car.add(cabin);

  // Hood scoop
  const scoopGeo = new THREE.BoxGeometry(0.6, 0.15, 0.5);
  const scoop = new THREE.Mesh(scoopGeo, bodyMat);
  scoop.position.set(1.0, 0.78, 0);
  car.add(scoop);

  // Spoiler
  const spoilerGeo = new THREE.BoxGeometry(0.15, 0.1, 1.5);
  const spoiler = new THREE.Mesh(spoilerGeo, bodyMat);
  spoiler.position.set(-1.55, 0.95, 0);
  car.add(spoiler);
  const spoilerStandGeo = new THREE.BoxGeometry(0.05, 0.25, 0.05);
  for(let s of [-0.5, 0.5]){
    const stand = new THREE.Mesh(spoilerStandGeo, chromeMat);
    stand.position.set(-1.55, 0.82, s);
    car.add(stand);
  }

  // Wheels
  const wheelGeo = new THREE.CylinderGeometry(0.28, 0.28, 0.2, 12);
  const wheelPositions = [
    [1.0, 0.28, 0.85], [1.0, 0.28, -0.85],
    [-1.0, 0.28, 0.85], [-1.0, 0.28, -0.85]
  ];
  const wheels = [];
  for(const [wx, wy, wz] of wheelPositions){
    const wheel = new THREE.Mesh(wheelGeo, wheelMat);
    wheel.rotation.x = Math.PI/2;
    wheel.position.set(wx, wy, wz);
    wheel.castShadow = true;
    car.add(wheel);
    wheels.push(wheel);

    // Hubcap
    const hubGeo = new THREE.CylinderGeometry(0.12, 0.12, 0.22, 8);
    const hub = new THREE.Mesh(hubGeo, chromeMat);
    hub.rotation.x = Math.PI/2;
    hub.position.set(wx, wy, wz);
    car.add(hub);
  }

  // Headlights
  const hlGeo = new THREE.SphereGeometry(0.1, 8, 8);
  const hlMat = new THREE.MeshPhongMaterial({color: 0xffffcc, emissive: 0xffff44, emissiveIntensity: 0.5});
  for(let s of [-0.5, 0.5]){
    const hl = new THREE.Mesh(hlGeo, hlMat);
    hl.position.set(1.61, 0.5, s);
    car.add(hl);
  }

  // Taillights
  const tlMat = new THREE.MeshPhongMaterial({color: 0xff0000, emissive: 0xff0000, emissiveIntensity: 0.3});
  for(let s of [-0.5, 0.5]){
    const tl = new THREE.Mesh(hlGeo, tlMat);
    tl.position.set(-1.61, 0.5, s);
    car.add(tl);
  }

  car.userData.wheels = wheels;
  return car;
}

// ─── Create Cars ───
const redCar = createCar(0xe61919);
const blueCar = createCar(0x1565c0);

// ─── Race Constants ───
const RACE_DISTANCE = 410; // start to finish
const RACE_DURATION = 7.0; // seconds for full race
const BLUE_LEAD = 0.08; // blue gets 8% time head start
const BLUE_SPEED = 0.75; // blue is 75% as fast as red

// ─── State ───
let raceTime = 0;
let won = false;
let winTimer = 0;
const RESET_TIME = 2.5;

// ─── Easing ───
function easeOutCubic(t){ return 1 - Math.pow(1 - t, 3); }
function easeInCubic(t){ return t * t * t; }

// ─── Animation ───
const clock = new THREE.Clock();

function animate(){
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);

  if(!won){
    raceTime += dt;

    // Red car progress (0 to 1 over race duration)
    const redT = Math.min(raceTime / RACE_DURATION, 1.0);
    const redDist = easeOutCubic(redT) * RACE_DISTANCE;

    // Blue car progress (slower, with head start)
    const blueAvailableTime = RACE_DURATION * BLUE_SPEED;
    const blueT = Math.min((raceTime - BLUE_LEAD * RACE_DURATION) / blueAvailableTime, 1.0);
    const blueDist = easeInCubic(Math.max(0, blueT)) * RACE_DISTANCE;

    // Position cars
    redCar.position.z = SL_Z + redDist;
    blueCar.position.z = SL_Z + blueDist;

    // Wheel rotation
    const wheelAngle = (redDist + blueDist) * 0.1;
    for(const w of redCar.userData.wheels) w.rotation.z = wheelAngle;
    for(const w of blueCar.userData.wheels) w.rotation.z = wheelAngle;

    // Check win
    if(redDist >= RACE_DISTANCE && !won){
      won = true;
      winTimer = 0;
    }
  } else {
    winTimer += dt;
    if(winTimer >= RESET_TIME){
      raceTime = 0;
      won = false;
      redCar.position.z = SL_Z;
      blueCar.position.z = SL_Z;
    }
  }

  // Camera
  const redZ = redCar.position.z;
  const blueZ = blueCar.position.z;
  const midZ = (redZ + blueZ) / 2;
  const spread = Math.abs(redZ - blueZ);

  const camZ = midZ + 20;
  const camY = 10 + spread * 0.04;
  const camX = 14 + spread * 0.02;

  camera.position.lerp(new THREE.Vector3(camX, camY, camZ), 0.06);
  camera.lookAt(0, 1.5, midZ + 5);

  renderer.render(scene, camera);
}

animate();

// ─── Resize ───
window.addEventListener('resize', ()=>{
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});
</script>
</body>
</html>
```
